function normalizeOptionalString(value) {
  return typeof value === 'string' && value.trim() ? value.trim() : ''
}

function slugify(value, fallback = 'revenue-intelligence-platform') {
  const normalized = normalizeOptionalString(value)
    .normalize('NFKD')
    .replace(/[^\w\s-]/gu, '')
    .trim()
    .replace(/[\s_]+/gu, '-')
    .replace(/-+/gu, '-')
    .toLocaleLowerCase()

  return normalized || fallback
}

function hasRevenuePlatformSignals({ contract }) {
  const surfaceText = Array.isArray(contract?.frontendSurfaces)
    ? contract.frontendSurfaces.flatMap((surface) => [surface?.key, surface?.label, surface?.path, ...(Array.isArray(surface?.screens) ? surface.screens : [])])
    : []
  const haystack = [
    contract?.domain?.label,
    contract?.domain?.slug,
    contract?.domain?.summary,
    ...(Array.isArray(contract?.roles) ? contract.roles : []),
    ...(Array.isArray(contract?.entities) ? contract.entities : []),
    ...(Array.isArray(contract?.workflows) ? contract.workflows : []),
    ...surfaceText,
  ].filter(Boolean).join(' ').toLocaleLowerCase()
  const signals = ['revenue', 'floe', 'scarlett', 'opportunity', 'campaign', 'pipeline', 'learning', 'conversation']
  return signals.filter((signal) => haystack.includes(signal)).length >= 5
}

