function baseRecord(collection, index = 1) {
  return {
    id: `seed-${collection}-${index}`,
    organizationId: 'org-floe-labs',
    workspaceId: 'ws-growth',
    status: 'active',
    source: 'seed',
    externalId: `${collection}-external-${index}`,
    idempotencyKey: `seed-${collection}-${index}`,
    name: COLLECTIONS.find(([name]) => name === collection)?.[1] || collection,
  }
}

